// One dataset row -> the same request the web form sends, marked as a test run (no CRM, no Telegram, no drafts).
const r = $json;
const run = 'EVAL-' + $execution.id;
return { json: { run: run, body: { name: '', email: 'test+' + r.case_id + '@example.com', company: String(r.company || ''), request: String(r.request || ''), budget: String(r.budget == null ? '' : r.budget), deadline: String(r.deadline == null ? '' : r.deadline), website: '', phone: '', hp_field: '', test_run: run, test_case: r.case_id } } };

// Compare the agent's real result (Tests sheet, written by the production workflow in test mode) with the expected values from the eval dataset.
function S(v) { return String(v == null ? '' : v).trim(); }
function num(v) { const s = S(v).replace(/\s/g, '').replace(',', '.'); if (s === '') return null; const n = Number(s); return isNaN(n) ? null : n; }
const exp = $('Evaluation Trigger').item.json;
const got = $json || {};
const found = !!S(got.lead_id || got.tier);
const issues = [];
// expected deadline: a number of weeks, or a date (deadlines like "by Christmas" depend on today)
function expWeeks(v) {
  if (S(v) === '') return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(S(v))) { const d = Date.parse(S(v) + 'T00:00:00Z'); const t = new Date(); const today = Date.UTC(t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()); return Math.round((d - today) / 864e5 / 7 * 10) / 10; }
  const n = num(v);
  if (n != null && n > 30000) { const d = Date.UTC(1899, 11, 30) + n * 864e5; const t = new Date(); const today = Date.UTC(t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()); return Math.round((d - today) / 864e5 / 7 * 10) / 10; } // Sheets date serial
  return n;
}
const eTier = S(exp.expected_tier), gTier = S(got.tier);
const injectionCaught = /possible_injection/.test(S(got.flags)) && gTier === 'ATTENTION';
let tier_ok, service_ok, budget_ok, deadline_ok;
if (!found) { tier_ok = service_ok = budget_ok = deadline_ok = 0; issues.push('no result row from the agent'); }
else if (injectionCaught) { tier_ok = service_ok = budget_ok = deadline_ok = 1; issues.push('injection caught by the code filter (no model call)'); }
else {
  tier_ok = (eTier === 'NOT_HIGH' ? gTier !== 'HIGH' : gTier === eTier) ? 1 : 0;
  if (!tier_ok) issues.push('tier ' + gTier + ' ≠ ' + eTier);
  service_ok = (!S(exp.expected_service) || S(got.service_id) === S(exp.expected_service)) ? 1 : 0;
  if (!service_ok) issues.push('service ' + S(got.service_id) + ' ≠ ' + S(exp.expected_service));
  const eb = num(exp.expected_budget_usd), gb = num(got.budget_usd_max);
  budget_ok = (eb == null ? gb == null : (gb != null && Math.abs(gb - eb) <= 1)) ? 1 : 0;
  if (!budget_ok) issues.push('budget ' + (gb == null ? '—' : gb) + ' ≠ ' + (eb == null ? '—' : eb));
  const ew = expWeeks(exp.expected_deadline), gw = num(got.deadline_weeks);
  deadline_ok = (ew == null ? gw == null : (gw != null && Math.abs(gw - ew) <= 0.6)) ? 1 : 0;
  if (!deadline_ok) issues.push('deadline ' + (gw == null ? '—' : gw) + ' wks ≠ ' + (ew == null ? '—' : ew));
}
const all_ok = (tier_ok && service_ok && budget_ok && deadline_ok) ? 1 : 0;
return { json: { got_tier: gTier, got_service: S(got.service_id), got_budget_usd: S(got.budget_usd_max), got_deadline_weeks: S(got.deadline_weeks), tier_ok, service_ok, budget_ok, deadline_ok, all_ok, issues: issues.join('; ') } };
